lookup.day_rate:
// PP 35/2021 art.32: the hourly wage is 1/173 of the monthly wage, fixed allowances in, at least 75% of the whole.
// proration_basis WORKING_DAYS: no statute fixes a part month. PP 36/2021 art.40(1) pays no wage for days not worked and art.17 values a day by working days (month ÷ 25 or ÷ 21), never by the calendar.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const hours = Number(get(terms, 'normal_hours_per_day', 8));
const sixDay = Number(get(terms, 'normal_days_per_week', 0)) === ctx.lookup.six_day_week;
const monthly =
	unit === 'DAILY'
		? amount * (sixDay ? ctx.lookup.daily_paid_days_six_day : ctx.lookup.daily_paid_days_five_day)
		: unit === 'HOURLY'
			? (amount * Number(get(terms, 'normal_hours_per_week', 0)) * 52) / 12
			: amount;
const allowances = Object.values(get(terms, 'allowances', {}));
const total = (kind) =>
	sum(
		allowances
			.filter((allowance) => get(allowance, 'variability', 'FIXED') === kind)
			.map((allowance) => Number(get(allowance, 'amount', 0)))
	);
const fixed = total('FIXED');
const wage = Math.max(
	monthly + fixed,
	ctx.lookup.wage_floor_factor * (monthly + fixed + total('VARIABLE'))
);
return (wage / ctx.lookup.divisor) * hours;
